contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint extra) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (10));
        require(address(this).balance >= 10);
        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;
        uint beforeBankBal = c.bank().balance;
        uint beforeContractBal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        bool reverted;
        c.play{value: 10}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint afterBankBal = c.bank().balance;
        uint afterContractBal = address(c).balance;
        uint afterThisBal = address(this).balance;

        assert(!reverted
            ? (afterPot == 0
                || afterPot == beforePot + 10)
            : (afterPot == beforePot
                && afterBankBal == beforeBankBal
                && afterContractBal == beforeContractBal
                && afterThisBal == beforeThisBal));
    }

    receive() external payable {}
}

