pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 extra) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 10);
        uint256 beforePot;
        try c.pot() returns (uint256 __r) { beforePot = __r; } catch { return; }
        uint beforeBankBal = c.bank().balance;
        uint beforeContractBal = address(c).balance;
        uint beforeThisBal = address(this).balance;
        bool reverted;
        try c.play{value: 10}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterPot;
        try c.pot() returns (uint256 __r) { afterPot = __r; } catch { return; }
        uint afterBankBal = c.bank().balance;
        uint afterContractBal = address(c).balance;
        uint afterThisBal = address(this).balance;
        assertTrue(!reverted
            ? (afterPot == 0
                || afterPot == beforePot + 10)
            : (afterPot == beforePot
                && afterBankBal == beforeBankBal
                && afterContractBal == beforeContractBal
                && afterThisBal == beforeThisBal));
    }

    function testFuzz_run(uint256 extra) public {
        _run(extra);
    }

    receive() external payable {}
}
